identity_assessment.text:
query IdentityAssessment($domain: String) {
  securityAssessment(domain: $domain) {
    overallScore
    overallScoreLevel
    assessmentFactors {
      riskFactorType
      severity
      likelihood
    }
  }
}

identity_list.text:
query IdentityList(
  $first: Int
  $after: Cursor
  $name: String
  $email: String
  $domains: [String!]
) {
  entities(
    archived: false
    primaryDisplayNamePattern: $name
    secondaryDisplayNamePattern: $email
    domains: $domains
    first: $first
    after: $after
  ) {
    nodes {
      entityId
      primaryDisplayName
      secondaryDisplayName
      type
      riskScore
      riskScoreSeverity
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

