identity_show.text:
query IdentityShow($entityIds: [UUID!]) {
  entities(entityIds: $entityIds, first: 1) {
    nodes {
      entityId
      primaryDisplayName
      secondaryDisplayName
      type
      riskScore
      riskScoreSeverity
      riskFactors {
        type
        severity
      }
      associations {
        bindingType
        ... on EntityAssociation {
          entity {
            entityId
            primaryDisplayName
          }
        }
        ... on LocalAdminLocalUserAssociation {
          accountName
        }
        ... on LocalAdminDomainEntityAssociation {
          entity {
            entityId
            primaryDisplayName
          }
        }
        ... on GeoLocationAssociation {
          geoLocation {
            country
            city
          }
        }
      }
      openIncidents(first: 10) {
        nodes {
          type
          startTime
          endTime
          compromisedEntities {
            entityId
            primaryDisplayName
          }
        }
        pageInfo {
          hasNextPage
        }
      }
      accounts {
        ... on ActiveDirectoryAccountDescriptor {
          domain
          samAccountName
          ou
          passwordAttributes {
            lastChange
          }
          expirationTime
        }
        ... on SsoUserAccountDescriptor {
          dataSource
          mostRecentActivity
          title
          creationTime
          passwordAttributes {
            lastChange
          }
        }
      }
    }
  }
}

identity_timeline.text:
query IdentityTimeline(
  $entityIds: [UUID!]
  $startTime: DateTimeInput
  $categories: [TimelineEventCategory!]
  $first: Int
  $after: Cursor
) {
  timeline(
    sourceEntityQuery: {entityIds: $entityIds}
    startTime: $startTime
    categories: $categories
    sortOrder: DESCENDING
    first: $first
    after: $after
  ) {
    nodes {
      eventId
      eventType
      eventSeverity
      timestamp
      ... on TimelineAlertEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
      }
      ... on TimelineUserOnEndpointActivityEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineAuthenticationEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineSuccessfulAuthenticationEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineFailedAuthenticationEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineServiceAccessEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineLdapSearchEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineDceRpcEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineRemoteCodeExecutionEvent {
        sourceEntity {
          entityId
          primaryDisplayName
        }
        targetEntity {
          entityId
          primaryDisplayName
        }
        geoLocation {
          country
          city
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
      ... on TimelineFileOperationEvent {
        targetEntity {
          entityId
          primaryDisplayName
        }
        userDisplayName
        endpointDisplayName
        ipAddress
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}
